function transform(message, context) {
  var apiUrl = context.environment === 'production'
    ? 'https://api.authorize.net/xml/v1/request.api'
    : 'https://apitest.authorize.net/xml/v1/request.api';

  context.set('apiUrl', apiUrl);

  var returnOptions = {
    showReceipt: true,
    url: context.returnUrl,
    urlText: 'Continue',
    cancelUrl: context.cancelUrl,
    cancelUrlText: 'Cancel'
  };

  var orderOptions = {
    show: true,
    merchantName: context.merchantName
  };

  var settings = [
    {
      settingName: 'hostedPaymentReturnOptions',
      settingValue: JSON.stringify(returnOptions)
    },
    {
      settingName: 'hostedPaymentButtonOptions',
      settingValue: JSON.stringify({ text: 'Pay Now' })
    },
    {
      settingName: 'hostedPaymentOrderOptions',
      settingValue: JSON.stringify(orderOptions)
    },
    {
      settingName: 'hostedPaymentBillingAddressOptions',
      settingValue: JSON.stringify({ show: true, required: false })
    },
    {
      settingName: 'hostedPaymentStyleOptions',
      settingValue: JSON.stringify({ bgColor: 'white' })
    }
  ];

  if (context.communicatorUrl) {
    settings.push({
      settingName: 'hostedPaymentIFrameCommunicatorUrl',
      settingValue: JSON.stringify({ url: context.communicatorUrl })
    });
  }

  var transactionRequest = {
    transactionType: 'authCaptureTransaction',
    amount: context.amount,
    order: {
      invoiceNumber: context.invoiceNumber || '',
      description: context.description
    }
  };

  message.payload = {
    getHostedPaymentPageRequest: {
      merchantAuthentication: {
        name: context.authNetLoginId,
        transactionKey: context.authNetTransactionKey
      },
      transactionRequest: transactionRequest,
      hostedPaymentSettings: {
        setting: settings
      }
    }
  };

  return message;
}

function transform(message, context) {
  var raw = message.payload;

  // Authorize.net prepends a UTF-8 BOM on some responses — strip it.
  if (typeof raw === 'string') {
    raw = raw.replace(/^\uFEFF/, '').trim();
    raw = JSON.parse(raw);
  }

  var resp = (raw && raw.getHostedPaymentPageResponse) ? raw.getHostedPaymentPageResponse : raw;
  var msgs = (resp && resp.messages) ? resp.messages : {};
  var resultCode = (msgs.resultCode || '').toLowerCase();

  if (resultCode !== 'ok' || !resp.token) {
    var msgList = msgs.message || [];
    var errText = msgList.length > 0
      ? '[' + msgList[0].code + '] ' + msgList[0].text
      : 'Unknown error from Authorize.net';
    throw new Error('Authorize.net getHostedPaymentPageRequest failed: ' + errText);
  }

  var formBase = context.environment === 'production'
    ? 'https://accept.authorize.net/payment/payment'
    : 'https://test.authorize.net/payment/payment';

  // The token must be POST-ed (not GET) to the form URL via Accept.js.
  // Return both the raw token and the target form URL so the caller has
  // everything needed to open the hosted payment window.
  message.payload = {
    token: resp.token,
    formUrl: formBase,
    environment: context.environment
  };

  return message;
}
